"nc-chat-container\">\n            <div class=\"nc-chat-header\" style=\"display:flex; align-items:center; padding:14px; background:#181818; border-bottom:1px solid #303030; gap:12px;\">\n                <button type=\"button\" class=\"nc-back-btn\" onclick=\"closeIndividualChat()\" aria-label=\"Back\" style=\"background:none; color:#fff; border:none; font-size:24px; cursor:pointer;\">‹</button>\n                <img id=\"icProfileImg\" class=\"nc-profile\" src=\"https://cdn-icons-png.flaticon.com/512/149/149071.png\" alt=\"User\" style=\"width:44px; height:44px; border-radius:50%; object-fit:cover; background:#333;\" />\n                <div class=\"nc-user-info\" style=\"flex:1; min-width:0;\">\n                    <h3 id=\"icPeerName\" style=\"font-size:16px; margin:0; color:#fff; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;\">USER</h3>\n                    <p id=\"icPeerSub\" style=\"font-size:12px; color:#25d366; margin:4px 0 0;\">● Direct Chat</p>\n                </div>\n            </div>\n            <div class=\"nc-chat-body\" id=\"icChatBody\" style=\"flex:1; overflow-y:auto; padding:15px 10px; display:flex; flex-direction:column; gap:10px; background:#0b0d0e;\">\n                <div class=\"nc-date-label\">TODAY</div>\n            </div>\n            <div class=\"nc-chat-footer\" style=\"display:flex; align-items:center; gap:8px; padding:10px 12px; background:#181818; border-top:1px solid #303030;\">\n                <input type=\"text\" id=\"icMessageInput\" class=\"nc-message-input\" placeholder=\"Message...\" autocomplete=\"off\" onkeydown=\"if(event.key==='Enter'){event.preventDefault();sendIndividualMessage();}\" style=\"flex:1; padding:10px 14px; border-radius:22px; border:1px solid #333; background:#242628; color:#fff; font-size:14px;\" />\n                <button type=\"button\" class=\"nc-send-btn\" onclick=\"sendIndividualMessage()\" aria-label=\"Send\" style=\"width:40px; height:40px; border-radius:50%; border:none; background:#00a884; color:#111b21; font-size:16px; font-weight:700; cursor:pointer;\">➤</button>\n            </div>\n        </div>\n    </div>\n    <!-- MYSELF PRIVATE SAVED CHAT OVERLAY -->\n    <div id=\"myselfOverlay\" style=\"display:none; position:fixed; top:0; left:0; right:0; bottom:65px; z-index:913; background:#080808; color:#fff; flex-direction:column;\">\n        <div class=\"nc-chat-container\">\n            <div class=\"nc-chat-header\" style=\"display:flex; align-items:center; padding:12px 14px; background:#181818; border-bottom:1px solid #303030; gap:12px; flex-shrink:0;\">\n                <button type=\"button\" onclick=\"closeMyselfPage()\" aria-label=\"Back\" style=\"background:none; color:#fff; border:none; font-size:24px; cursor:pointer;\">‹</button>\n                <div style=\"width:40px; height:40px; border-radius:50%; background:#00a884; color:#111b21; display:flex; align-items:center; justify-content:center; font-size:16px; flex-shrink:0;\"><i class=\"fa-solid fa-bookmark\"></i></div>\n                <div style=\"flex:1; min-width:0;\">\n                    <h3 id=\"msHeaderName\" style=\"font-size:15px; margin:0; color:#fff; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;\">Myself</h3>\n                    <p style=\"font-size:11px; color:#25d366; margin:2px 0 0;\">● Private · Only you can see this</p>\n                </div>\n                <button type=\"button\" onclick=\"openBuildNetworkPage()\" title=\"Broadcast\" aria-label=\"Broadcast\" style=\"background:none; color:#25d366; border:none; font-size:18px; cursor:pointer; padding:4px; flex-shrink:0;\"><i class=\"fa-solid fa-tower-broadcast\"></i></button>\n            </div>\n            <div class=\"nc-chat-body\" id=\"msChatBody\" style=\"flex:1 1 auto; min-height:0; overflow-y:auto; padding:15px 10px; display:flex; flex-direction:column; gap:10px; background:#0b0d0e;\"></div>\n            <div id=\"msAttachPanel\" style=\"display:none; flex:1 1 auto; min-height:0; overflow-y:auto; padding:12px; flex-direction:column; gap:10px; background:#0b0d0e;\">\n                <div class=\"profile-feed-media-editor\" style=\"margin:0;\">\n                    <span class=\"profile-feed-media-prompt\">Add text</span>\n                    <input type=\"text\" id=\"msPanelTextInput\" placeholder=\"Write text...\" autocomplete=\"off\" oninput=\"syncMyselfTextFromPanel(this.value)\" onkeydown=\"if(event.key==='Enter'){event.preventDefault();sendMyselfItem();}\" style=\"width:100%; padding:9px 12px; border-radius:8px; border:1px solid #165e63; background:#071316; color:#fff; font-size:13px; outline:none;\" />\n                </div>\n                <div class=\"profile-feed-media-editor\" style=\"margin:0;\">\n                    <span class=\"profile-feed-media-prompt\">Add image</span>\n                    <label class=\"profile-feed-upload\">Choose image<input type=\"file\" accept=\"image/*\" onchange=\"onMyselfFileSelected(this)\"></label>\n                </div>\n                <div class=\"profile-feed-media-editor\" style=\"margin:0;\">\n                    <span class=\"profile-feed-media-prompt\">Add video</span>\n                    <label class=\"profile-feed-upload\">Choose video<input type=\"file\" accept=\"video/*\" onchange=\"onMyselfFileSelected(this)\"></label>\n                </div>\n                <div class=\"profile-feed-media-editor\" style=\"margin:0;\">\n                    <span class=\"profile-feed-media-prompt\">Add audio</span>\n                    <label class=\"profile-feed-upload\">Choose audio<input type=\"file\" accept=\"audio/*\" onchange=\"onMyselfFileSelected(this)\"></label>\n                </div>\n                <div class=\"profile-feed-media-editor\" style=\"margin:0;\">\n                    <span class=\"profile-feed-media-prompt\">Add file</span>\n                    <label class=\"profile-feed-upload\">Choose file<input type=\"file\" accept=\".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.zip,.csv,*/*\" onchange=\"onMyselfFileSelected(this)\"></label>\n                </div>\n            </div>\n            <div id=\"msPendingFileBar\" style=\"display:none; padding:6px 12px; background:#14171a; border-top:1px solid #2a2f33; font-size:12px; color:#25d366; align-items:center; justify-content:space-between; gap:8px; flex-shrink:0;\">\n                <span id=\"msPendingFileName\" style=\"overflow:hidden; text-overflow:ellipsis; white-space:nowrap;\"></span>\n                <button type=\"button\" onclick=\"clearMyselfPendingFile()\" style=\"background:none; border:none; color:#ff6b6b; cursor:pointer; font-size:14px; font-weight:700;\">×</button>\n            </div>\n            <div class=\"nc-chat-footer\" style=\"display:flex; align-items:center; gap:8px; padding:10px 12px; background:#181818; border-top:1px solid #303030; flex-shrink:0;\">\n                <input type=\"text\" id=\"msMessageInput\" class=\"nc-message-input\" placeholder=\"Tap to add text, image, video, audio, file...\" autocomplete=\"off\" onfocus=\"openMyselfComposer()\" onclick=\"openMyselfComposer()\" oninput=\"syncMyselfTextFromBar(this.value)\" onkeydown=\"if(event.key==='Enter'){event.preventDefault();sendMyselfItem();}\" style=\"flex:1; padding:10px 14px; border-radius:22px; border:1px solid #333; background:#242628; color:#fff; font-size:14px;\" />\n                <button type=\"button\" id=\"msSendBtn\" class=\"nc-send-btn\" onclick=\"sendMyselfItem()\" aria-label=\"Send\" style=\"width:40px; height:40px; border-radius:50%; border:none; background:#00a884; color:#111b21; font-size:16px; font-weight:700; cursor:pointer; flex-shrink:0;\">➤</button>\n            </div>\n        </div>\n    </div>\n    <!-- AUTHOR PROFILE OVERLAY (READ-ONLY) -->\n    <div id=\"authorProfileOverlay\" style=\"display:none; position:fixed; top:0; left:0; right:0; bottom:65px; z-index:915; background:#080808; color:#fff; flex-direction:column; overflow-y:auto;\">\n        <div class=\"company-category-header\" style=\"position:sticky; top:0; z-index:3; background:#080808; display:flex; align-items:center;\">\n            <button type=\"button\" class=\"company-cat-btn\" id=\"apTabInfo\" onclick=\"switchAuthorProfileTab('info', this)\">INFO</button>\n            <button type=\"button\" class=\"company-cat-btn active\" id=\"apTabFeed\" onclick=\"switchAuthorProfileTab('feed', this)\">FEED</button>\n        </div>\n        <div id=\"apInfoSection\" style=\"display:none; padding:20px 16px;\">\n            <div class=\"profile-info-section\">\n                <h2 class=\"profile-name-title\" id=\"apInfoName\">Name <i class=\"fa-solid fa-circle-check verified-badge\"></i></h2>\n                <div class=\"profile-handle\" id=\"apInfoHandle\">@username</div>\n                <div class=\"profile-about-tag\" id=\"apInfoAbout\">About:</div>\n                <p id=\"apInfoBio\" style=\"color:#aaa; font-size:13px; margin-top:8px;\">Public Infinity profile.</p>\n            </div>\n        </div>\n        <div id=\"apFeedSection\" style=\"display:block;\">\n            <div class=\"profile-info-section\" style=\"display:none;\">\n                <div class=\"profile-info-top-row\">\n                    <div class=\"profile-feed-avatar-wrap readonly\">\n                        <img class=\"profile-feed-avatar-img\" id=\"apAuthorAvatarImg\" data-feed-avatar-img alt=\"Profile\" />\n                    </div>\n                    <div class=\"profile-info-text-col\">\n                        <h2 class=\"profile-name-title\" id=\"apAuthorName\">Name <i class=\"fa-solid fa-circle-check verified-badge\"></i></h2>\n                        <div class=\"profile-handle\" id=\"apAuthorHandle\">@username</div>\n                        <div class=\"profile-about-tag\">About:</div>\n                        <div class=\"profile-contact-icons-row\" data-readonly=\"true\">\n                            <button type=\"button\" class=\"profile-contact-icon-btn\" id=\"apContactPhoneBtn\" data-contact-kind=\"phone\" onclick=\"window.handleProfileContactIconClick('phone', this)\" title=\"Call\" aria-label=\"Call\"><i class=\"fa-solid fa-phone\"></i></button>\n                            <button type=\"button\" class=\"profile-contact-icon-btn\" id=\"apContactEmailBtn\" data-contact-kind=\"email\" onclick=\"window.handleProfileContactIconClick('email', this)\" title=\"Mail\" aria-label=\"Mail\"><i class=\"fa-solid fa-envelope\"></i></button>\n                            <button type=\"button\" class=\"profile-contact-icon-btn\" id=\"apContactLocationBtn\" data-contact-kind=\"location\" onclick=\"window.handleProfileContactIconClick('location', this)\" title=\"Location\" aria-label=\"Location\"><i class=\"fa-solid fa-location-dot\"></i></button>\n                        </div>\n                    </div>\n                </div>\n                <div class=\"profile-stats-grid\">\n                    <div class=\"stat-item\"><span class=\"stat-value\" id=\"apLikesCount\">0</span><span class=\"stat-label\">Likes</span></div>\n                    <div class=\"stat-item\"><span class=\"stat-value\" id=\"apRepostsCount\">0</span><span class=\"stat-label\">Reposts</span></div>\n                    <div class=\"stat-item\"><span class=\"stat-value\" id=\"apCommentsCount\">0</span><span class=\"stat-label\">Comments</span></div>\n                    <div class=\"stat-item\" style=\"display:flex;align-items:center;justify-content:center;\"><button type=\"button\" id=\"apSupportBtn\" class=\"follow-btn\" onclick=\"toggleFollow(this)\" style=\"padding:6px 12px;border-radius:16px;font-size:0.75rem;font-weight:700;cursor:pointer;\">+ SUPPORT</button></div>\n                </div>\n            </div>\n            <div class=\"profile-tabs-header\">\n                <button type=\"button\" class=\"profile-tab-btn active\" onclick=\"filterAuthorProfileTab('all', this)\"><i class=\"fa-solid fa-border-all\"></i></button>\n                <button type=\"button\" class=\"profile-tab-btn\" onclick=\"filterAuthorProfileTab('image', this)\"><i class=\"fa-solid fa-images\"></i></button>\n                <button type=\"button\" class=\"profile-tab-btn\" onclick=\"filterAuthorProfileTab('video', this)\"><i class=\"fa-solid fa-video\"></i></button>\n                <button type=\"button\" class=\"profile-tab-btn\" onclick=\"filterAuthorProfileTab('audio', this)\" aria-label=\"Audio posts\"><i class=\"fa-solid fa-music\"></i></button>\n                <button type=\"button\" class=\"profile-tab-btn\" onclick=\"filterAuthorProfileTab('file', this)\" aria-label=\"File posts\"><i class=\"fa-solid fa-file-lines\"></i></button>\n            </div>\n            <div class=\"social-feed\" id=\"apPostsFeed\" style=\"padding:12px; display:flex; flex-direction:column; gap:16px;\"></div>\n        </div>\n    </div>\n    <!-- SHARE TO ACCOUNTS OVERLAY -->\n    <div id=\"shareAccountsOverlay\" style=\"display:none; position:fixed; top:0; left:0; right:0; bottom:65px; z-index:920; background:#111315; color:#e9edef; overflow-y:auto; flex-direction:column; padding-bottom:76px;\">\n        <div style=\"display:flex; align-items:center; gap:10px; padding:10px 14px; background:#181a1c; border-bottom:1px solid #2a2f33; position:sticky; top:0; z-index:3;\">\n            <button type=\"button\" onclick=\"closeShareToAccountsPage()\" aria-label=\"Back\" style=\"background:none; border:none; color:#fff; font-size:18px; cursor:pointer; padding:4px;\"><i class=\"fa-solid fa-arrow-left\"></i></button>\n            <input type=\"text\" id=\"saSearchInput\" oninput=\"onShareAccountsSearchInput(this.value)\" placeholder=\"Search @username...\" autocomplete=\"off\" style=\"flex:1; background:#23272c; border:1px solid #32373e; border-radius:20px; padding:8px 14px; color:#fff; font-size:14px; outline:none;\" />\n            <button type=\"button\" onclick=\"clearShareAccountsSearch()\" aria-label=\"Clear\" style=\"background:none; border:none; color:#9ba3ab; font-size:16px; cursor:pointer; padding:4px;\"><i class=\"fa-solid fa-xmark\"></i></button>\n        </div>\n        <div style=\"padding:10px 16px 4px; font-size:12px; font-weight:700; color:#9ba3ab;\">Accounts on Infinity</div>\n        <div id=\"saAccountsList\" style=\"display:flex; flex-direction:column;\"></div>\n        <button type=\"button\" id=\"saSendBtn\" onclick=\"submitShareToAccounts()\" aria-label=\"Send\" style=\"position:fixed; right:20px; bottom:84px; width:54px; height:54px; border-radius:16px; border:none; background:#00a884; color:#111b21; font-size:20px; font-weight:700; display:flex; align-items:center; justify-content:center; box-shadow:0 4px 16px rgba(0,0,0,0.45); cursor:pointer; z-index:5;\"><i class=\"fa-solid fa-arrow-right\"></i></button>\n    </div>";